28	  hh,
29	  h,
30	  l,
31	  ll,
32	  j,
33	  z,
34	  t,
35	  L,
36	#if defined(LIBC_INTERNAL_PRINTF_CONVERT_FLOAT128)
37	  Q,
38	#endif // LIBC_INTERNAL_PRINTF_CONVERT_FLOAT128
39	#ifndef LIBC_COPT_PRINTF_DISABLE_BITINT
40	  w,
41	  wf,
42	#endif // LIBC_COPT_PRINTF_DISABLE_BITINT
43	  none
44	};
