51	// Type large enough to store the raw bits of any floating point type.
52	//
53	// Does not use any specialization of FPBits, because it is unavailable on
54	// PowerPC.
55	using AnyFloatStorageType = UInt128;
56	
57	enum FormatFlags : uint8_t {
58	  LEFT_JUSTIFIED = 0x01, // -
59	  FORCE_SIGN = 0x02,     // +
60	  SPACE_PREFIX = 0x04,   // space
61	  ALTERNATE_FORM = 0x08, // #
62	  LEADING_ZEROES = 0x10, // 0
63	
64	  // These flags come from the GNU extensions which aren't yet implemented.
65	  //  group_decimals = 0x20, // '
66	  //  locale_digits = 0x40,  // I
67	};
68	
69	struct FormatSection {
70	  bool has_conv;
71	
72	  cpp::string_view raw_string;
73	
74	  // Format Specifier Values
75	  FormatFlags flags = FormatFlags(0);
76	  LengthModifier length_modifier = LengthModifier::none;
77	  size_t bit_width = 0;
78	  int min_width = 0;
79	  int precision = -1;
80	
81	  AnyFloatStorageType conv_val_raw;
82	  void *conv_val_ptr;
83	
84	  char conv_name;
85	
86	  // This operator is only used for testing and should be automatically
87	  // optimized out for release builds.
88	  LIBC_INLINE bool operator==(const FormatSection &other) const {
89	    if (has_conv != other.has_conv)
90	      return false;
91	
92	    if (raw_string != other.raw_string)
93	      return false;
94	
95	    if (has_conv) {
96	      if (!((static_cast<uint8_t>(flags) ==
97	             static_cast<uint8_t>(other.flags)) &&
98	            (min_width == other.min_width) && (precision == other.precision) &&
99	            (bit_width == other.bit_width) &&
100	            (length_modifier == other.length_modifier) &&
101	            (conv_name == other.conv_name)))
102	        return false;
103	
104	      if (conv_name == 'p' || conv_name == 'n' || conv_name == 's')
105	        return (conv_val_ptr == other.conv_val_ptr);
106	      else if (conv_name != '%')
107	        return (conv_val_raw == other.conv_val_raw);
108	    }
109	    return true;
110	  }
111	};
112	
113	enum PrimaryType : uint8_t {
114	  Unknown = 0,
115	  Float = 1,
116	  Pointer = 2,
117	  Integer = 3,
118	  FixedPoint = 4,
119	};
