135	    constexpr bool IS_POINTER = cpp::is_pointer_v<T>;
136	    constexpr bool IS_FLOAT = cpp::is_floating_point_v<T>;
137	#ifdef LIBC_INTERNAL_PRINTF_HAS_FIXED_POINT
138	    constexpr bool IS_FIXED_POINT = cpp::is_fixed_point_v<T>;
139	#else
140	    constexpr bool IS_FIXED_POINT = false;
141	#endif // LIBC_INTERNAL_PRINTF_HAS_FIXED_POINT
142	
143	    return TypeDesc{sizeof(T), IS_POINTER       ? PrimaryType::Pointer
144	                               : IS_FLOAT       ? PrimaryType::Float
145	                               : IS_FIXED_POINT ? PrimaryType::FixedPoint
146	                                                : PrimaryType::Integer};
147	  }
148	}
