1	//===-- Format string parser for printf -------------------------*- C++ -*-===//
2	//
3	// Part of the LLVM Project, under the Apache License v2.0 with LLVM Exceptions.
4	// See https://llvm.org/LICENSE.txt for license information.
5	// SPDX-License-Identifier: Apache-2.0 WITH LLVM-exception
6	//
7	//===----------------------------------------------------------------------===//
8	
9	#ifndef LLVM_LIBC_SRC___SUPPORT_PRINTF_CORE_PARSER_H
10	#define LLVM_LIBC_SRC___SUPPORT_PRINTF_CORE_PARSER_H
11	
12	#include "include/llvm-libc-macros/stdfix-macros.h"
13	#include "src/__support/CPP/algorithm.h" // max
14	#include "src/__support/CPP/limits.h"
15	#include "src/__support/CPP/optional.h"
16	#include "src/__support/CPP/type_traits.h"
17	#include "src/__support/macros/config.h"
18	#include "src/__support/macros/properties/types.h"
19	#include "src/__support/printf_core/core_structs.h"
20	#include "src/__support/printf_core/printf_config.h"
21	#include "src/__support/str_to_integer.h"
22	
23	#include <stddef.h>
24	
25	#ifdef LIBC_INTERNAL_PRINTF_HAS_FIXED_POINT
26	#include "src/__support/fixed_point/fx_rep.h"
27	#endif // LIBC_INTERNAL_PRINTF_HAS_FIXED_POINT
28	#ifndef LIBC_COPT_PRINTF_DISABLE_STRERROR
29	#include "src/__support/libc_errno.h"
30	#endif // LIBC_COPT_PRINTF_DISABLE_STRERROR
31	#ifndef LIBC_COPT_PRINTF_DISABLE_WIDE
32	#include "hdr/types/wint_t.h"
33	#endif // LIBC_COPT_PRINTF_DISABLE_WIDE
34	
35	namespace LIBC_NAMESPACE_DECL {
36	namespace printf_core {
37	
38	template <typename T, typename U = void> struct int_type_of {
39	  using type = T;
40	};
41	
42	template <typename T>
43	struct int_type_of<T, cpp::enable_if_t<cpp::is_same_v<T, double>
44	#if !defined(LIBC_TYPES_LONG_DOUBLE_IS_DOUBLE_DOUBLE)
45	                                       || cpp::is_same_v<T, long double>
46	#endif // LIBC_TYPES_LONG_DOUBLE_IS_DOUBLE_DOUBLE
47	#if defined(LIBC_TYPES_HAS_FLOAT128)
48	                                       || cpp::is_same_v<T, float128>
49	#endif // LIBC_TYPES_HAS_FLOAT128
50	                                       >> {
51	  using type = typename fputil::FPBits<T>::StorageType;
52	};
53	
54	#ifdef LIBC_INTERNAL_PRINTF_HAS_FIXED_POINT
55	template <typename T>
56	struct int_type_of<T, cpp::enable_if<cpp::is_fixed_point_v<T>>> {
57	  using type = typename fixed_point::FXRep<T>::StorageType;
58	};
59	#endif // LIBC_INTERNAL_PRINTF_HAS_FIXED_POINT
60	
61	template <typename T> using int_type_of_v = typename int_type_of<T>::type;
62	
63	#ifndef LIBC_COPT_PRINTF_DISABLE_INDEX_MODE
64	#define WRITE_ARG_VAL_SIMPLEST(dst, arg_type, index)                           \
65	  {                                                                            \
66	    auto temp = get_arg_value<arg_type>(index);                                \
67	    if (!temp.has_value()) {                                                   \
68	      section.has_conv = false;                                                \
69	    } else {                                                                   \
70	      dst = static_cast<decltype(dst)>(                                        \
71	          cpp::bit_cast<int_type_of_v<arg_type>>(temp.value()));               \
72	    }                                                                          \
73	  }
74	#else
75	#define WRITE_ARG_VAL_SIMPLEST(dst, arg_type, _)                               \
76	  dst = cpp::bit_cast<int_type_of_v<arg_type>>(get_next_arg_value<arg_type>())
77	#endif // LIBC_COPT_PRINTF_DISABLE_INDEX_MODE
78	
79	template <typename ArgProvider> class Parser {
80	  const char *__restrict str;
81	
82	  size_t cur_pos = 0;
83	  ArgProvider args_cur;
84	
85	#ifndef LIBC_COPT_PRINTF_DISABLE_INDEX_MODE
86	  // args_start stores the start of the va_args, which helps in getting the
87	  // number of arguments that have already been passed. args_index is tracked
88	  // so that we know which argument args_cur is on.
89	  ArgProvider args_start;
90	  size_t args_index = 1;
91	
92	  // Defined in printf_config.h
93	  static constexpr size_t DESC_ARR_LEN = LIBC_COPT_PRINTF_INDEX_ARR_LEN;
94	
95	  // desc_arr stores the sizes of the variables in the ArgProvider. This is used
96	  // in index mode to reduce repeated string parsing. The sizes are stored as
97	  // TypeDesc objects, which store the size as well as minimal type information.
98	  // This is necessary because some systems separate the floating point and
99	  // integer values in va_args.
100	  TypeDesc desc_arr[DESC_ARR_LEN] = {type_desc_from_type<void>()};
101	
102	  // TODO: Look into object stores for optimization.
103	
104	#endif // LIBC_COPT_PRINTF_DISABLE_INDEX_MODE
105	
106	public:
107	#ifndef LIBC_COPT_PRINTF_DISABLE_INDEX_MODE
108	  LIBC_INLINE Parser(const char *__restrict new_str, ArgProvider &args)
109	      : str(new_str), args_cur(args), args_start(args) {}
110	#else
111	  LIBC_INLINE Parser(const char *__restrict new_str, ArgProvider &args)
112	      : str(new_str), args_cur(args) {}
113	#endif // LIBC_COPT_PRINTF_DISABLE_INDEX_MODE
114	
115	  // get_next_section will parse the format string until it has a fully
116	  // specified format section. This can either be a raw format section with no
117	  // conversion, or a format section with a conversion that has all of its
118	  // variables stored in the format section.
119	  LIBC_INLINE FormatSection get_next_section() {
120	    FormatSection section;
121	    size_t starting_pos = cur_pos;
122	    if (str[cur_pos] == '%') {
123	      // format section
124	      section.has_conv = true;
125	
126	      ++cur_pos;
127	      [[maybe_unused]] size_t conv_index = 0;
128	
129	#ifndef LIBC_COPT_PRINTF_DISABLE_INDEX_MODE
130	      conv_index = parse_index(&cur_pos);
131	#endif // LIBC_COPT_PRINTF_DISABLE_INDEX_MODE
132	
133	      section.flags = parse_flags(&cur_pos);
134	
135	      // handle width
136	      section.min_width = 0;
137	      if (str[cur_pos] == '*') {
138	        ++cur_pos;
139	
140	        WRITE_ARG_VAL_SIMPLEST(section.min_width, int, parse_index(&cur_pos));
141	      } else if (internal::isdigit(str[cur_pos])) {
142	        auto result = internal::strtointeger<int>(str + cur_pos, 10);
143	        section.min_width = result.value;
144	        cur_pos = cur_pos + static_cast<size_t>(result.parsed_len);
145	      }
146	      if (section.min_width < 0) {
147	        section.min_width =
148	            (section.min_width == INT_MIN) ? INT_MAX : -section.min_width;
149	        section.flags = static_cast<FormatFlags>(section.flags |
150	                                                 FormatFlags::LEFT_JUSTIFIED);
151	      }
152	
153	      // handle precision
154	      section.precision = -1; // negative precisions are ignored.
155	      if (str[cur_pos] == '.') {
156	        ++cur_pos;
157	        section.precision = 0; // if there's a . but no specified precision, the
158	                               // precision is implicitly 0.
159	        if (str[cur_pos] == '*') {
160	          ++cur_pos;
161	
162	          WRITE_ARG_VAL_SIMPLEST(section.precision, int, parse_index(&cur_pos));
163	
164	        } else if (internal::isdigit(str[cur_pos])) {
165	          auto result = internal::strtointeger<int>(str + cur_pos, 10);
166	          section.precision = result.value;
167	          cur_pos = cur_pos + static_cast<size_t>(result.parsed_len);
168	        }
169	      }
170	
171	      auto [lm, bw] = parse_length_modifier(&cur_pos);
172	      section.length_modifier = lm;
173	      section.conv_name = str[cur_pos];
174	      section.bit_width = bw;
175	      switch (str[cur_pos]) {
176	      case ('%'):
177	        // Regardless of options, a % conversion is always safe. The standard
178	        // says that "The complete conversion specification shall be %%" but it
179	        // also says that "If a conversion specification is invalid, the
180	        // behavior is undefined." Based on that we define that any conversion
181	        // specification ending in '%' shall display as '%' regardless of any
182	        // valid or invalid options.
183	        section.has_conv = true;
184	        break;
185	      case ('c'):
186	        if (section.length_modifier == LengthModifier::l) {
187	#ifdef LIBC_COPT_PRINTF_DISABLE_WIDE
188	          using WideCharArgType = int;
189	#else
190	          using WideCharArgType = wint_t;
191	#endif // LIBC_COPT_PRINTF_DISABLE_WIDE
192	          WRITE_ARG_VAL_SIMPLEST(section.conv_val_raw, WideCharArgType,
193	                                 conv_index);
194	        } else {
195	          WRITE_ARG_VAL_SIMPLEST(section.conv_val_raw, int, conv_index);
196	        }
197	        break;
198	      case ('d'):
199	      case ('i'):
200	      case ('o'):
201	      case ('x'):
202	      case ('X'):
203	      case ('u'):
204	      case ('b'):
205	      case ('B'):
206	        switch (lm) {
207	        case (LengthModifier::hh):
208	        case (LengthModifier::h):
209	        case (LengthModifier::none):
210	          WRITE_ARG_VAL_SIMPLEST(section.conv_val_raw, int, conv_index);
211	          break;
212	        case (LengthModifier::l):
213	          WRITE_ARG_VAL_SIMPLEST(section.conv_val_raw, long, conv_index);
214	          break;
215	        case (LengthModifier::ll):
216	        case (LengthModifier::L): // This isn't in the standard, but is in other
217	                                  // libc implementations.
218	
219	          WRITE_ARG_VAL_SIMPLEST(section.conv_val_raw, long long, conv_index);
220	          break;
221	        case (LengthModifier::j):
222	
223	          WRITE_ARG_VAL_SIMPLEST(section.conv_val_raw, intmax_t, conv_index);
224	          break;
225	        case (LengthModifier::z):
226	
227	          WRITE_ARG_VAL_SIMPLEST(section.conv_val_raw, size_t, conv_index);
228	          break;
229	        case (LengthModifier::t):
230	
231	          WRITE_ARG_VAL_SIMPLEST(section.conv_val_raw, ptrdiff_t, conv_index);
232	          break;
233	
234	#ifndef LIBC_COPT_PRINTF_DISABLE_BITINT
235	        case (LengthModifier::w):
236	        case (LengthModifier::wf):
237	          if (bw == 0) {
238	            section.has_conv = false;
239	          } else if (bw <= cpp::numeric_limits<unsigned int>::digits) {
240	            WRITE_ARG_VAL_SIMPLEST(section.conv_val_raw, int, conv_index);
241	          } else if (bw <= cpp::numeric_limits<unsigned long>::digits) {
242	            WRITE_ARG_VAL_SIMPLEST(section.conv_val_raw, long, conv_index);
243	          } else if (bw <= cpp::numeric_limits<unsigned long long>::digits) {
244	            WRITE_ARG_VAL_SIMPLEST(section.conv_val_raw, long long, conv_index);
245	          } else {
246	            WRITE_ARG_VAL_SIMPLEST(section.conv_val_raw, intmax_t, conv_index);
247	          }
248	          break;
249	#endif // LIBC_COPT_PRINTF_DISABLE_BITINT
250	#if defined(LIBC_INTERNAL_PRINTF_CONVERT_FLOAT128)
251	        case (LengthModifier::Q):
252	          section.has_conv = false;
253	          break;
254	#endif // LIBC_INTERNAL_PRINTF_CONVERT_FLOAT128
255	        }
256	        break;
257	#ifndef LIBC_COPT_PRINTF_DISABLE_FLOAT
258	      case ('f'):
259	      case ('F'):
260	      case ('e'):
261	      case ('E'):
262	      case ('a'):
263	      case ('A'):
264	      case ('g'):
265	      case ('G'):
266	        switch (lm) {
267	#if defined(LIBC_INTERNAL_PRINTF_CONVERT_FLOAT128)
268	        case (LengthModifier::Q):
269	          WRITE_ARG_VAL_SIMPLEST(section.conv_val_raw, float128, conv_index);
270	          break;
271	#endif // LIBC_INTERNAL_PRINTF_CONVERT_FLOAT128
272	#ifndef LIBC_TYPES_LONG_DOUBLE_IS_DOUBLE_DOUBLE
273	        case (LengthModifier::L):
274	          WRITE_ARG_VAL_SIMPLEST(section.conv_val_raw, long double, conv_index);
275	          break;
276	#endif // !LIBC_TYPES_LONG_DOUBLE_IS_DOUBLE_DOUBLE
277	        default:
278	          WRITE_ARG_VAL_SIMPLEST(section.conv_val_raw, double, conv_index);
279	          break;
280	        }
281	        break;
282	#endif // LIBC_COPT_PRINTF_DISABLE_FLOAT
283	#ifdef LIBC_INTERNAL_PRINTF_HAS_FIXED_POINT
284	      // Capitalization represents sign, but we only need to get the right
285	      // bitwidth here so we ignore that.
286	      case ('r'):
287	      case ('R'):
288	        // all fract sizes we support are less than 32 bits, and currently doing
289	        // va_args with fixed point types just doesn't work.
290	        // TODO: Move to fixed point types once va_args supports it.
291	        WRITE_ARG_VAL_SIMPLEST(section.conv_val_raw, uint32_t, conv_index);
292	        break;
293	      case ('k'):
294	      case ('K'):
295	        if (lm == LengthModifier::l) {
296	          WRITE_ARG_VAL_SIMPLEST(section.conv_val_raw, uint64_t, conv_index);
297	        } else {
298	          WRITE_ARG_VAL_SIMPLEST(section.conv_val_raw, uint32_t, conv_index);
299	        }
300	        break;
301	#endif // LIBC_INTERNAL_PRINTF_HAS_FIXED_POINT
302	#ifndef LIBC_COPT_PRINTF_DISABLE_STRERROR
303	      case ('m'):
304	        // %m is an odd conversion in that it doesn't consume an argument, it
305	        // just takes the current value of errno as its argument.
306	        section.conv_val_raw =
307	            static_cast<fputil::FPBits<double>::StorageType>(libc_errno);
308	        break;
309	#endif // LIBC_COPT_PRINTF_DISABLE_STRERROR
310	#ifndef LIBC_COPT_PRINTF_DISABLE_WRITE_INT
311	      case ('n'): // Intentional fallthrough
312	#endif            // LIBC_COPT_PRINTF_DISABLE_WRITE_INT
313	      case ('p'):
314	        WRITE_ARG_VAL_SIMPLEST(section.conv_val_ptr, void *, conv_index);
315	        break;
316	      case ('s'):
317	        WRITE_ARG_VAL_SIMPLEST(section.conv_val_ptr, void *, conv_index);
318	        break;
319	      default:
320	        // if the conversion is undefined, change this to a raw section.
321	        section.has_conv = false;
322	        break;
323	      }
324	      // If the end of the format section is on the '\0'. This means we need to
325	      // not advance the cur_pos.
326	      if (str[cur_pos] != '\0')
327	        ++cur_pos;
328	
329	    } else {
330	      // raw section
331	      section.has_conv = false;
332	      while (str[cur_pos] != '%' && str[cur_pos] != '\0')
333	        ++cur_pos;
334	    }
335	    section.raw_string = {str + starting_pos, cur_pos - starting_pos};
336	    return section;
337	  }
338	
339	private:
340	  // parse_flags parses the flags inside a format string. It assumes that
341	  // str[*local_pos] is inside a format specifier, and parses any flags it
342	  // finds. It returns a FormatFlags object containing the set of found flags
343	  // arithmetically or'd together. local_pos will be moved past any flags found.
344	  LIBC_INLINE FormatFlags parse_flags(size_t *local_pos) {
345	    bool found_flag = true;
346	    FormatFlags flags = FormatFlags(0);
347	    while (found_flag) {
348	      switch (str[*local_pos]) {
349	      case '-':
350	        flags = static_cast<FormatFlags>(flags | FormatFlags::LEFT_JUSTIFIED);
351	        break;
352	      case '+':
353	        flags = static_cast<FormatFlags>(flags | FormatFlags::FORCE_SIGN);
354	        break;
355	      case ' ':
356	        flags = static_cast<FormatFlags>(flags | FormatFlags::SPACE_PREFIX);
357	        break;
358	      case '#':
359	        flags = static_cast<FormatFlags>(flags | FormatFlags::ALTERNATE_FORM);
360	        break;
361	      case '0':
362	        flags = static_cast<FormatFlags>(flags | FormatFlags::LEADING_ZEROES);
363	        break;
364	      default:
365	        found_flag = false;
366	      }
367	      if (found_flag)
368	        ++*local_pos;
369	    }
370	    return flags;
371	  }
372	
373	  // parse_length_modifier parses the length modifier inside a format string. It
374	  // assumes that str[*local_pos] is inside a format specifier. It returns a
375	  // LengthModifier with the length modifier it found. It will advance local_pos
376	  // after the format specifier if one is found.
377	  LIBC_INLINE LengthSpec parse_length_modifier(size_t *local_pos) {
378	    switch (str[*local_pos]) {
379	    case ('l'):
380	      if (str[*local_pos + 1] == 'l') {
381	        *local_pos += 2;
382	        return {LengthModifier::ll, 0};
383	      } else {
384	        ++*local_pos;
385	        return {LengthModifier::l, 0};
386	      }
387	#ifndef LIBC_COPT_PRINTF_DISABLE_BITINT
388	    case ('w'): {
389	      LengthModifier lm;
390	      if (str[*local_pos + 1] == 'f') {
391	        *local_pos += 2;
392	        lm = LengthModifier::wf;
393	      } else {
394	        ++*local_pos;
395	        lm = LengthModifier::w;
396	      }
397	      if (internal::isdigit(str[*local_pos])) {
398	        const auto result = internal::strtointeger<int>(str + *local_pos, 10);
399	        *local_pos += static_cast<size_t>(result.parsed_len);
400	        return {lm, static_cast<size_t>(cpp::max(0, result.value))};
401	      }
402	      return {lm, 0};
403	    }
404	#endif // LIBC_COPT_PRINTF_DISABLE_BITINT
405	    case ('h'):
406	      if (str[*local_pos + 1] == 'h') {
407	        *local_pos += 2;
408	        return {LengthModifier::hh, 0};
409	      } else {
410	        ++*local_pos;
411	        return {LengthModifier::h, 0};
412	      }
413	    case ('L'):
414	      ++*local_pos;
415	      return {LengthModifier::L, 0};
416	#if defined(LIBC_INTERNAL_PRINTF_CONVERT_FLOAT128)
417	    case ('Q'):
418	      ++*local_pos;
419	      return {LengthModifier::Q, 0};
420	#endif // LIBC_INTERNAL_PRINTF_CONVERT_FLOAT128
421	    case ('j'):
422	      ++*local_pos;
423	      return {LengthModifier::j, 0};
424	    case ('z'):
425	      ++*local_pos;
426	      return {LengthModifier::z, 0};
427	    case ('t'):
428	      ++*local_pos;
429	      return {LengthModifier::t, 0};
430	    default:
431	      return {LengthModifier::none, 0};
432	    }
433	  }
434	
435	  // get_next_arg_value gets the next value from the arg list as type T.
436	  template <class T> LIBC_INLINE T get_next_arg_value() {
437	    return args_cur.template next_var<T>();
438	  }
439	
440	  //----------------------------------------------------
441	  // INDEX MODE ONLY FUNCTIONS AFTER HERE:
442	  //----------------------------------------------------
443	
444	#ifndef LIBC_COPT_PRINTF_DISABLE_INDEX_MODE
445	
446	  // parse_index parses the index of a value inside a format string. It
447	  // assumes that str[*local_pos] points to character after a '%' or '*', and
448	  // returns 0 if there is no closing $, or if it finds no number. If it finds a
449	  // number, it will move local_pos past the end of the $, else it will not move
450	  // local_pos.
451	  LIBC_INLINE size_t parse_index(size_t *local_pos) {
452	    if (internal::isdigit(str[*local_pos])) {
453	      auto result = internal::strtointeger<int>(str + *local_pos, 10);
454	      size_t index = static_cast<size_t>(result.value);
455	      if (str[*local_pos + static_cast<size_t>(result.parsed_len)] != '$')
456	        return 0;
457	      *local_pos = static_cast<size_t>(1 + result.parsed_len) + *local_pos;
458	      return index;
459	    }
460	    return 0;
461	  }
462	
463	  LIBC_INLINE void set_type_desc(size_t index, TypeDesc value) {
464	    if (index != 0 && index <= DESC_ARR_LEN)
465	      desc_arr[index - 1] = value;
466	  }
467	
468	  // get_arg_value gets the value from the arg list at index (starting at 1).
469	  // This may require parsing the format string. An index of 0 is interpreted as
470	  // the next value. If the format string is not valid, it may have gaps in its
471	  // indexes. Requesting the value for any index after a gap will fail, since
472	  // the arg list must be read in order and with the correct types.
473	  template <class T> LIBC_INLINE cpp::optional<T> get_arg_value(size_t index) {
474	    if (!(index == 0 || index == args_index)) {
475	      bool success = args_to_index(index);
476	      if (!success) {
477	        // If we can't get to this index, then the value of the arg can't be
478	        // found.
479	        return cpp::optional<T>();
480	      }
481	    }
482	
483	    set_type_desc(index, type_desc_from_type<T>());
484	
485	    ++args_index;
486	    return get_next_arg_value<T>();
487	  }
488	
489	  // the ArgProvider can only return the next item in the list. This function is
490	  // used in index mode when the item that needs to be read is not the next one.
491	  // It moves cur_args to the index requested so the appropriate value may
492	  // be read. This may involve parsing the format string, and is in the worst
493	  // case an O(n^2) operation.
494	  LIBC_INLINE bool args_to_index(size_t index) {
495	    if (args_index > index) {
496	      args_index = 1;
497	      args_cur = args_start;
498	    }
499	
500	    while (args_index < index) {
501	      TypeDesc cur_type_desc = type_desc_from_type<void>();
502	      if (args_index <= DESC_ARR_LEN)
503	        cur_type_desc = desc_arr[args_index - 1];
504	
505	      if (cur_type_desc == type_desc_from_type<void>())
506	        cur_type_desc = get_type_desc(args_index);
507	
508	      // A type of void represents the type being unknown. If the type for the
509	      // requested index isn't in the desc_arr and isn't found by parsing the
510	      // string, then then advancing to the requested index is impossible. In
511	      // that case the function returns false.
512	      if (cur_type_desc == type_desc_from_type<void>())
513	        return false;
514	
515	      if (cur_type_desc == type_desc_from_type<uint32_t>())
516	        args_cur.template next_var<uint32_t>();
517	      else if (cur_type_desc == type_desc_from_type<uint64_t>())
518	        args_cur.template next_var<uint64_t>();
519	#ifndef LIBC_COPT_PRINTF_DISABLE_FLOAT
520	      // Floating point numbers are stored separately from the other arguments.
521	      else if (cur_type_desc == type_desc_from_type<double>())
522	        args_cur.template next_var<double>();
523	#ifndef LIBC_TYPES_LONG_DOUBLE_IS_DOUBLE_DOUBLE
524	      else if (cur_type_desc == type_desc_from_type<long double>())
525	        args_cur.template next_var<long double>();
526	#endif // !LIBC_TYPES_LONG_DOUBLE_IS_DOUBLE_DOUBLE
527	#endif // LIBC_COPT_PRINTF_DISABLE_FLOAT
528	#ifdef LIBC_INTERNAL_PRINTF_HAS_FIXED_POINT
529	      // Floating point numbers may be stored separately from the other
530	      // arguments.
531	      else if (cur_type_desc == type_desc_from_type<short fract>())
532	        args_cur.template next_var<short fract>();
533	      else if (cur_type_desc == type_desc_from_type<fract>())
534	        args_cur.template next_var<fract>();
535	      else if (cur_type_desc == type_desc_from_type<long fract>())
536	        args_cur.template next_var<long fract>();
537	      else if (cur_type_desc == type_desc_from_type<short accum>())
538	        args_cur.template next_var<short accum>();
539	      else if (cur_type_desc == type_desc_from_type<accum>())
540	        args_cur.template next_var<accum>();
541	      else if (cur_type_desc == type_desc_from_type<long accum>())
542	        args_cur.template next_var<long accum>();
543	#endif // LIBC_INTERNAL_PRINTF_HAS_FIXED_POINT
544	      // pointers may be stored separately from normal values.
545	      else if (cur_type_desc == type_desc_from_type<void *>())
546	        args_cur.template next_var<void *>();
547	      else
548	        args_cur.template next_var<uint32_t>();
549	
550	      ++args_index;
551	    }
552	    return true;
553	  }
554	
555	  // get_type_desc assumes that this format string uses index mode. It iterates
556	  // through the format string until it finds a format specifier that defines
557	  // the type of index, and returns a TypeDesc describing that type. It does not
558	  // modify cur_pos.
559	  LIBC_INLINE TypeDesc get_type_desc(size_t index) {
560	    // index mode is assumed, and the indices start at 1, so an index
561	    // of 0 is invalid.
562	    size_t local_pos = 0;
563	
564	    while (str[local_pos]) {
565	      if (str[local_pos] == '%') {
566	        ++local_pos;
567	
568	        size_t conv_index = parse_index(&local_pos);
569	
570	        // the flags aren't relevant for this situation, but I need to skip past
571	        // them so they're parsed but the result is discarded.
572	        parse_flags(&local_pos);
573	
574	        // handle width
575	        if (str[local_pos] == '*') {
576	          ++local_pos;
577	
578	          size_t width_index = parse_index(&local_pos);
579	          set_type_desc(width_index, type_desc_from_type<int>());
580	          if (width_index == index)
581	            return type_desc_from_type<int>();
582	
583	        } else if (internal::isdigit(str[local_pos])) {
584	          while (internal::isdigit(str[local_pos]))
585	            ++local_pos;
586	        }
587	
588	        // handle precision
589	        if (str[local_pos] == '.') {
590	          ++local_pos;
591	          if (str[local_pos] == '*') {
592	            ++local_pos;
593	
594	            size_t precision_index = parse_index(&local_pos);
595	            set_type_desc(precision_index, type_desc_from_type<int>());
596	            if (precision_index == index)
597	              return type_desc_from_type<int>();
598	
599	          } else if (internal::isdigit(str[local_pos])) {
600	            while (internal::isdigit(str[local_pos]))
601	              ++local_pos;
602	          }
603	        }
604	
605	        auto [lm, bw] = parse_length_modifier(&local_pos);
606	
607	        // if we don't have an index for this conversion, then its position is
608	        // unknown and all this information is irrelevant. The rest of this
609	        // logic has been for skipping past this conversion properly to avoid
610	        // weirdness with %%.
611	        if (conv_index == 0) {
612	          if (str[local_pos] != '\0')
613	            ++local_pos;
614	          continue;
615	        }
616	
617	        TypeDesc conv_size = type_desc_from_type<void>();
618	        switch (str[local_pos]) {
619	        case ('%'):
620	          conv_size = type_desc_from_type<void>();
621	          break;
622	        case ('c'):
623	          if (lm == LengthModifier::l) {
624	#ifdef LIBC_COPT_PRINTF_DISABLE_WIDE
625	            using WideCharArgType = int;
626	#else
627	            using WideCharArgType = wint_t;
628	#endif // LIBC_COPT_PRINTF_DISABLE_WIDE
629	            conv_size = type_desc_from_type<WideCharArgType>();
630	          } else {
631	            conv_size = type_desc_from_type<int>();
632	          }
633	          break;
634	        case ('d'):
635	        case ('i'):
636	        case ('o'):
637	        case ('x'):
638	        case ('X'):
639	        case ('u'):
640	        case ('b'):
641	        case ('B'):
642	          switch (lm) {
643	          case (LengthModifier::hh):
644	          case (LengthModifier::h):
645	          case (LengthModifier::none):
646	            conv_size = type_desc_from_type<int>();
647	            break;
648	          case (LengthModifier::l):
649	            conv_size = type_desc_from_type<long>();
650	            break;
651	          case (LengthModifier::ll):
652	          case (LengthModifier::L): // This isn't in the standard, but is in
653	                                    // other libc implementations.
654	            conv_size = type_desc_from_type<long long>();
655	            break;
656	          case (LengthModifier::j):
657	            conv_size = type_desc_from_type<intmax_t>();
658	            break;
659	          case (LengthModifier::z):
660	            conv_size = type_desc_from_type<size_t>();
661	            break;
662	          case (LengthModifier::t):
663	            conv_size = type_desc_from_type<ptrdiff_t>();
664	            break;
665	#ifndef LIBC_COPT_PRINTF_DISABLE_BITINT
666	          case (LengthModifier::w):
667	          case (LengthModifier::wf):
668	            if (bw <= cpp::numeric_limits<unsigned int>::digits) {
669	              conv_size = type_desc_from_type<int>();
670	            } else if (bw <= cpp::numeric_limits<unsigned long>::digits) {
671	              conv_size = type_desc_from_type<long>();
672	            } else if (bw <= cpp::numeric_limits<unsigned long long>::digits) {
673	              conv_size = type_desc_from_type<long long>();
674	            } else {
675	              conv_size = type_desc_from_type<intmax_t>();
676	            }
677	            break;
678	#endif // LIBC_COPT_PRINTF_DISABLE_BITINT
679	#if defined(LIBC_INTERNAL_PRINTF_CONVERT_FLOAT128)
680	          case (LengthModifier::Q):
681	            conv_size = type_desc_from_type<void>();
682	            break;
683	#endif // LIBC_INTERNAL_PRINTF_CONVERT_FLOAT128
684	          }
685	          break;
686	#ifndef LIBC_COPT_PRINTF_DISABLE_FLOAT
687	        case ('f'):
688	        case ('F'):
689	        case ('e'):
690	        case ('E'):
691	        case ('a'):
692	        case ('A'):
693	        case ('g'):
694	        case ('G'):
695	          switch (lm) {
696	#if defined(LIBC_INTERNAL_PRINTF_CONVERT_FLOAT128)
697	          case LengthModifier::Q:
698	            conv_size = type_desc_from_type<float128>();
699	            break;
700	#endif // LIBC_INTERNAL_PRINTF_CONVERT_FLOAT128
701	#ifndef LIBC_TYPES_LONG_DOUBLE_IS_DOUBLE_DOUBLE
702	          case LengthModifier::L:
703	            conv_size = type_desc_from_type<long double>();
704	            break;
705	#endif // !LIBC_TYPES_LONG_DOUBLE_IS_DOUBLE_DOUBLE
706	          default:
707	            conv_size = type_desc_from_type<double>();
708	            break;
709	          }
710	          break;
711	#endif // LIBC_COPT_PRINTF_DISABLE_FLOAT
712	#ifdef LIBC_INTERNAL_PRINTF_HAS_FIXED_POINT
713	        // Capitalization represents sign, but we only need to get the right
714	        // bitwidth here so we ignore that.
715	        case ('r'):
716	        case ('R'):
717	          conv_size = type_desc_from_type<uint32_t>();
718	          break;
719	        case ('k'):
720	        case ('K'):
721	          if (lm == LengthModifier::l) {
722	            conv_size = type_desc_from_type<uint64_t>();
723	          } else {
724	            conv_size = type_desc_from_type<uint32_t>();
725	          }
726	          break;
727	#endif // LIBC_INTERNAL_PRINTF_HAS_FIXED_POINT
728	#ifndef LIBC_COPT_PRINTF_DISABLE_WRITE_INT
729	        case ('n'):
730	#endif // LIBC_COPT_PRINTF_DISABLE_WRITE_INT
731	        case ('p'):
732	        case ('s'):
733	          conv_size = type_desc_from_type<void *>();
734	          break;
735	        default:
736	          conv_size = type_desc_from_type<int>();
737	          break;
738	        }
739	
740	        set_type_desc(conv_index, conv_size);
741	        if (conv_index == index)
742	          return conv_size;
743	      }
744	      // If the end of the format section is on the '\0'. This means we need to
745	      // not advance the local_pos.
746	      if (str[local_pos] != '\0')
747	        ++local_pos;
748	    }
749	
750	    // If there is no size for the requested index, then it's unknown. Return
751	    // void.
752	    return type_desc_from_type<void>();
753	  }
754	
755	#endif // LIBC_COPT_PRINTF_DISABLE_INDEX_MODE
756	};
757	
758	} // namespace printf_core
759	} // namespace LIBC_NAMESPACE_DECL
760	
761	#endif // LLVM_LIBC_SRC___SUPPORT_PRINTF_CORE_PARSER_H
762

