173	  LIBC_INLINE int pad(char new_char, size_t length) {
174	    // First, fill as much of the buffer as possible with the padding char.
175	    size_t written = 0;
176	    const size_t buff_space = wb.buff_len - wb.buff_cur;
177	    // ASSERT: length > buff_space
178	    if (buff_space > 0) {
179	      inline_memset(wb.buff + wb.buff_cur, new_char, buff_space);
180	      wb.buff_cur += buff_space;
181	      written = buff_space;
182	    }
183	
184	    // Next, overflow write the rest of length using the mini_buff.
185	    constexpr size_t MINI_BUFF_SIZE = 64;
186	    char mini_buff[MINI_BUFF_SIZE];
187	    inline_memset(mini_buff, new_char, MINI_BUFF_SIZE);
188	    cpp::string_view mb_string_view(mini_buff, MINI_BUFF_SIZE);
189	    while (written + MINI_BUFF_SIZE < length) {
190	      int result = wb.overflow_write(mb_string_view);
191	      if (result != WRITE_OK)
192	        return result;
193	      written += MINI_BUFF_SIZE;
194	    }
195	    cpp::string_view mb_substr = mb_string_view.substr(0, length - written);
196	    return wb.overflow_write(mb_substr);
197	  }
