203	  // to the overflow mechanism to be handled separately.
204	  LIBC_INLINE int write(cpp::string_view new_string) {
205	    chars_written += new_string.size();
206	    if (LIBC_LIKELY(wb.buff_cur + new_string.size() <= wb.buff_len)) {
207	      inline_memcpy(wb.buff + wb.buff_cur, new_string.data(),
208	                    new_string.size());
209	      wb.buff_cur += new_string.size();
210	      return WRITE_OK;
211	    }
212	    return wb.overflow_write(new_string);
213	  }
214	
215	  // Takes a char and a length, memsets the next length characters of the buffer
216	  // if there is space, else calls pad which will loop and call the overflow
217	  // mechanism on a secondary buffer.
218	  LIBC_INLINE int write(char new_char, size_t length) {
219	    chars_written += length;
220	
