231	  // to the overflow mechanism to be handled separately.
232	  LIBC_INLINE int write(char new_char) {
233	    chars_written += 1;
234	    if (LIBC_LIKELY(wb.buff_cur + 1 <= wb.buff_len)) {
235	      wb.buff[wb.buff_cur] = new_char;
236	      wb.buff_cur += 1;
237	      return WRITE_OK;
238	    }
239	    cpp::string_view char_string_view(&new_char, 1);
240	    return wb.overflow_write(char_string_view);
241	  }
