template <WriteMode write_mode>
ErrorOr<size_t> printf_main_modular(Writer<write_mode> *writer,
                                    const char *__restrict str,
                                    internal::ArgList &args) {
  Parser<internal::ArgList> parser(str, args);
  int result = 0;
